// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        bool ok;
        address reportedOwner;
        vm.prank(actor);
        try c.owner() returns (address o) {
            ok = true;
            reportedOwner = o;
        } catch {
            ok = false;
            reportedOwner = address(0);
        }

        assertTrue(ok == false || reportedOwner != actor);
    }
}
